pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        string memory result = c.version();
        assertTrue(keccak256(abi.encodePacked(result)) == keccak256(abi.encodePacked("1.0.0")));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(true);
        bool reverted; try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(msg.sender != c.DEPOSITOR_ACCOUNT() ? reverted == true : true);
    }
}

