// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Admissible domain: any address can call, but we specifically test the zero address.
        address caller = address(0);
        bool ok;
        // Call setL1BlockValues as the zero address and observe revert/success.
        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference contract, caller != depositorAccount (which is DEPOSITOR_ACCOUNT),
        // so the require should fail and the call should revert.
        // In the buggy contract, caller == address(0) passes the require, so the call succeeds.
        // The general rule: A call from address(0) to setL1BlockValues must revert.
        assertTrue(!ok);
    }
}

